(function(){'use strict';var container=document.querySelector('.mw-mc-container');if(!container)return;if(container.dataset.searchInstalled)return;container.dataset.searchInstalled='1';var wrap=document.createElement('div');wrap.className='mw-mc-search-wrap';wrap.innerHTML='<div class="mw-mc-search-field">'+'<svg class="mw-mc-search-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">'+'<circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/>'+'</svg>'+'<input type="text" class="mw-mc-search-input" placeholder="Search customer, address, service…" '+'autocomplete="off" autocorrect="off" spellcheck="false" aria-label="Search schedule">'+'<button type="button" class="mw-mc-search-clear" aria-label="Clear search" hidden>&times;</button>'+'</div>'+'<div class="mw-mc-search-count" role="status" aria-live="polite"></div>';var topBar=container.querySelector('.mw-mc-topbar');if(topBar&&topBar.nextSibling){container.insertBefore(wrap,topBar.nextSibling)}else{container.insertBefore(wrap,container.firstChild)}
var input=wrap.querySelector('.mw-mc-search-input');var clear=wrap.querySelector('.mw-mc-search-clear');var count=wrap.querySelector('.mw-mc-search-count');function normalize(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
var cards=null;var cardText=null;function rebuildCardIndex(){cards=Array.prototype.slice.call(container.querySelectorAll('.mw-mc-card'));cardText=cards.map(function(el){return normalize(el.textContent)})}
function applyFilter(query){if(!cards)rebuildCardIndex();var q=normalize(query).trim();var shown=0;for(var i=0;i<cards.length;i++){var hit=q===''||cardText[i].indexOf(q)!==-1;cards[i].style.display=hit?'':'none';if(hit)shown++}
if(q===''){count.textContent='';wrap.classList.remove('mw-mc-search-active')}else{wrap.classList.add('mw-mc-search-active');count.textContent=shown===0?'No stops match "'+query+'"':shown+' match'+(shown===1?'':'es')}
clear.hidden=q===''}
var debounceTimer=null;input.addEventListener('input',function(){clearTimeout(debounceTimer);debounceTimer=setTimeout(function(){applyFilter(input.value)},120)});input.addEventListener('keydown',function(e){if(e.key==='Escape'){input.value='';applyFilter('');input.blur()}});clear.addEventListener('click',function(){input.value='';applyFilter('');input.focus()});if(typeof MutationObserver!=='undefined'){var mo=new MutationObserver(function(){cards=null;if(input.value)applyFilter(input.value);});mo.observe(container,{childList:!0,subtree:!0})}}())